const $=id=>document.getElementById(id);
let configs=[],current=0,chosen=new Set(),needsConfirm=false,rules=[],page={row:0,col:0,total_rows:0,total_columns:0},lastCheck=null;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const clone=x=>JSON.parse(JSON.stringify(x));
const modes=[['number','Число'],['category','Категория / бинарный ответ'],['text','Открытый ответ'],['checkbox','Вариант множественного выбора'],['date','Дата'],['datetime','Дата и время'],['time','Время'],['duration','Продолжительность']];
const dateModes=['date','datetime','time','duration'];
const inputFormats={date:[['%d.%m.%Y','ДД.ММ.ГГГГ'],['%Y-%m-%d','ГГГГ-ММ-ДД'],['%d/%m/%Y','ДД/ММ/ГГГГ'],['%m/%d/%Y','ММ/ДД/ГГГГ']],datetime:[['%Y-%m-%d %H:%M:%S','ГГГГ-ММ-ДД ЧЧ:ММ:СС'],['%d.%m.%Y %H:%M:%S','ДД.ММ.ГГГГ ЧЧ:ММ:СС'],['%d.%m.%Y %H:%M','ДД.ММ.ГГГГ ЧЧ:ММ'],['%Y-%m-%dT%H:%M:%S','ГГГГ-ММ-ДДTЧЧ:ММ:СС']],time:[['%H:%M:%S','ЧЧ:ММ:СС'],['%H:%M','ЧЧ:ММ'],['%I:%M %p','ЧЧ:ММ AM/PM']],duration:[['duration','ЧЧ:ММ:СС (часы могут быть больше 24)']]};
const outputFormats={date:[['EDATE10','ДД.ММ.ГГГГ'],['SDATE10','ГГГГ/ММ/ДД'],['ADATE10','ММ/ДД/ГГГГ'],['DATE11','ДД-МЕС-ГГГГ']],datetime:[['DATETIME20','Дата + время (DATETIME)'],['YMDHMS19','ГГГГ-ММ-ДД ЧЧ:ММ:СС']],time:[['TIME8','ЧЧ:ММ:СС'],['TIME5','ЧЧ:ММ']],duration:[['TIME8','Часы:минуты:секунды'],['DTIME11','Дни + время']]};
inputFormats.date.push(['%Y-%m-%d %H:%M:%S','ГГГГ-ММ-ДД ЧЧ:ММ:СС (дата Excel)'],['%d.%m.%y','ДД.ММ.ГГ (00–68 → 2000–2068; 69–99 → 1969–1999)']);
inputFormats.datetime.push(['%Y-%m-%d %H:%M','ГГГГ-ММ-ДД ЧЧ:ММ']);
function status(s){$('status').textContent=s}
function safe(fn){return async(...args)=>{try{await fn(...args)}catch(e){status(e.message)}}}
async function api(path,p){return BrowserEngine.route(path,p)}
function payload(){if(!configs.length)throw Error('Загрузите данные.');if(needsConfirm&&!$('confirm').checked)throw Error('Проверьте соответствие столбцов и отметьте галочку над списком переменных.');return {configs,options:{trim:$('trim').checked}}}
function select(id,options,value,extra=''){return `<select id="${id}" ${extra}>${options.map(([v,t])=>`<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(t)}</option>`).join('')}</select>`}
function table(columns,rows){return `<table><thead><tr>${columns.map(c=>`<th>${esc(c)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(v=>`<td>${v===null||v===undefined?'—':esc(v)}</td>`).join('')}</tr>`).join('')}</tbody></table>`}
function download(blob,name){let a=document.createElement('a');const url=URL.createObjectURL(blob);a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
async function b64(file){return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result.split(',')[1]);r.onerror=reject;r.readAsDataURL(file)})}
function answers(c){return Object.keys(c.frequencies).filter(v=>v.trim()!=='')}
function invalidate(){lastCheck=null;$('checkResults').innerHTML='';$('checkSummary').textContent='';$('distTables').innerHTML='';$('previewTable').innerHTML='';$('pageInfo').textContent='Настройки изменены — обновите просмотр.'}
function refreshLists(){
 for(let id of ['checkVars','distVars']){const old=new Set([...$(id).selectedOptions].map(o=>o.value));$(id).innerHTML=configs.filter(c=>c.include).map(c=>`<option value="${esc(c.name)}" ${old.has(c.name)?'selected':''}>${esc(c.name)} — ${esc(c.label)}</option>`).join('')}
 renderRules();
}
function renderList(){const query=$('search').value.toLowerCase();$('variableList').innerHTML=configs.map((c,i)=>({c,i})).filter(({c})=>(c.source+' '+c.name).toLowerCase().includes(query)).map(({c,i})=>`<div class="item ${i===current?'active':''}"><input type="checkbox" data-chosen="${i}" aria-label="Выбрать ${esc(c.name)}" ${chosen.has(i)?'checked':''}><button type="button" data-open="${i}"><b>${i+1}. ${esc(c.name)}</b>${c.include?'':' · исключена'}<br>${esc(c.source)}<br><small>${esc(modes.find(([v])=>v===c.mode)?.[1]||c.mode)}</small></button></div>`).join('');
 $('variableList').querySelectorAll('[data-open]').forEach(el=>el.onclick=()=>{current=+el.dataset.open;render()});
 $('variableList').querySelectorAll('[data-chosen]').forEach(el=>el.onchange=()=>{el.checked?chosen.add(+el.dataset.chosen):chosen.delete(+el.dataset.chosen);renderTargets()});
}
const bulkOptions=[['mode','Способ обработки'],['measure','Уровень измерения'],['missing','Коды пропусков и пустые ячейки'],['format','Форматы дат и чисел'],['mapping','Коды ответов']];
$('bulkFields').innerHTML=bulkOptions.map(([v,t])=>`<label><input type="checkbox" id="bulk_${v}" ${v==='measure'?'checked':''}> ${t}</label>`).join('');
function renderTargets(){$('bulkTargets').innerHTML=`<small>Выбрано получателей: ${[...chosen].filter(i=>i!==current).length}. Можно выбрать одну или несколько переменных здесь или слева.</small>`+configs.map((c,i)=>i===current?'':`<label><input type="checkbox" data-target="${i}" ${chosen.has(i)?'checked':''}>${esc(c.name)} — ${esc(c.source.slice(0,100))}</label>`).join('');$('bulkTargets').querySelectorAll('[data-target]').forEach(el=>el.onchange=()=>{el.checked?chosen.add(+el.dataset.target):chosen.delete(+el.dataset.target);renderList()})}
function changeMode(c){c.blank='missing';if(c.mode==='text')c.measure='nominal';if(dateModes.includes(c.mode)){c.measure='scale';c.input_format=inputFormats[c.mode][0][0];c.date_display=outputFormats[c.mode][0][0]}
 if(c.mode==='category'&&!Object.keys(c.mapping).length)answers(c).forEach((v,i)=>c.mapping[v]=i+1);
}
function render(){
 renderList();renderTargets();const c=configs[current],isDate=dateModes.includes(c.mode),missing=c.missing_codes||[];
 $('editor').innerHTML=`<h2>${esc(c.source)}</h2><label><input id="include" type="checkbox" ${c.include?'checked':''}> Включить в экспорт</label><div class="row"><label>Имя SPSS<input id="name" value="${esc(c.name)}"></label><label>Уровень измерения${c.mode==='text'?'<input value="Номинальный" disabled>':select('measure',[['nominal','Номинальный'],['ordinal','Порядковый'],['scale','Количественный (Scale)']],c.measure)}</label></div><label>Подпись вопроса<input id="label" value="${esc(c.label)}"></label><label>Способ обработки${select('mode',modes,c.mode)}</label>
 ${isDate?`<div class="row"><label>Формат входящих значений${select('input_format',inputFormats[c.mode],c.input_format)}</label><label>Формат отображения в SPSS${select('date_display',outputFormats[c.mode],c.date_display)}</label></div>`:c.mode==='number'?`<label>Знаков после запятой в SPSS<input id="decimals" type="number" min="0" max="15" value="${c.decimals??2}"></label>`:''}
 ${c.mode!=='text'?`<label>Выбрать пропущенные значения — числовые коды</label><div class="codes">${[0,1,2].map(i=>`<input type="number" step="any" data-missing="${i}" aria-label="Код пропуска ${i+1}" placeholder="Код ${i+1}" value="${esc(missing[i]??'')}">`).join('')}</div><p class="muted">До трёх кодов. Эти значения сохраняются в файле и объявляются пользовательскими пропусками SPSS; валидные проценты их исключают.</p><label>Пустая ячейка${select('blank',[['missing','Системный пропуск'],...(c.mode==='checkbox'?[['zero','0 — не выбрано']]:[['0','0']]),...missing.map(v=>[String(v),String(v)+' — выбранный код']),...(needsConfirm?[['reference','Как в образце по ID']]:[]),...(!['missing','zero','0','reference',...missing.map(String)].includes(String(c.blank))?[[String(c.blank),String(c.blank)]]:[])],c.blank)}</label>`:'<p class="badge">String — исходный текст без числовых кодов</p>'}
 <details><summary>Дополнительно: текстовые обозначения пропусков</summary><label>Ответы, заменяемые системным пропуском (по одному на строку)<textarea id="missing_tokens" rows="2">${esc((c.missing_tokens||[]).join('\n'))}</textarea></label></details>
 ${c.mode==='checkbox'?`<label>Название группы множественного выбора<input id="group" value="${esc(c.group)}"></label><p class="muted">Непустое значение → 1. Пустое — по настройке выше.</p>`:''}
 ${(c.conflicts||[]).length?'<div class="note">В образце есть неоднозначные соответствия. Проверьте коды и пропуски.</div>':''}
 <h3>${c.mode==='category'?'Ответы и коды':'Найденные ответы'}</h3>${c.mode==='category'?`<div class="toolbar"><button type="button" id="binary01">Два ответа: 0 / 1</button><button type="button" id="binary12">Два ответа: 1 / 2</button><button type="button" id="binaryCustom" class="secondary">Другое</button></div><div id="customCodes" class="${c.custom_binary?'':'hidden'}"><div class="row"><label>Код первого ответа<input type="number" step="any" id="customFirst" value="${c.custom_first??0}"></label><label>Код второго ответа<input type="number" step="any" id="customSecond" value="${c.custom_second??1}"></label></div><button type="button" id="applyBinary">Применить свою кодировку</button></div><p class="muted">Коды назначаются двум непустым ответам в порядке строк таблицы ниже. Проверьте направление кодировки.</p>`:''}
 <div class="scroll"><table><tr><th>Ответ</th><th>Частота</th>${c.mode==='category'?'<th>Код</th>':''}</tr>${Object.entries(c.frequencies).map(([v,n])=>`<tr><td>${esc(v||'(пусто)')}</td><td>${n}</td>${c.mode==='category'?`<td>${v.trim()?`<input type="number" step="any" data-answer="${esc(v)}" value="${esc(c.mapping[v]??'')}">`:''}</td>`:''}</tr>`).join('')}</table></div>`;
 for(const field of ['include','name','measure','label','mode','blank','group','missing_tokens','input_format','date_display','decimals']){const el=$(field);if(!el)continue;el.onchange=()=>{c[field]=field==='include'?el.checked:field==='missing_tokens'?el.value.split('\n').filter(Boolean):field==='decimals'?Math.max(0,Math.min(15,+el.value)):el.value;if(field==='mode')changeMode(c);invalidate();refreshLists();if(['mode','blank'].includes(field))render();else renderList()}}
 $('editor').querySelectorAll('[data-missing]').forEach(el=>el.onchange=()=>{c.missing_codes=[...$('editor').querySelectorAll('[data-missing]')].map(e=>e.value).filter(v=>v!=='').map(Number);c.reference_missing=[];invalidate();render()});
 $('editor').querySelectorAll('[data-answer]').forEach(el=>el.onchange=()=>{c.mapping[el.dataset.answer]=el.value;c.value_labels={};invalidate()});
 if(c.mode==='category'){
  $('binary01').onclick=safe(()=>binary(c,0,1));$('binary12').onclick=safe(()=>binary(c,1,2));
  $('binaryCustom').onclick=()=>{c.custom_binary=!c.custom_binary;render()};
  $('applyBinary').onclick=safe(()=>{if($('customFirst').value===''||$('customSecond').value==='')throw Error('Укажите оба кода.');c.custom_first=+$('customFirst').value;c.custom_second=+$('customSecond').value;binary(c,c.custom_first,c.custom_second)});
 }
}
function binary(c,a,b){const keys=answers(c);if(keys.length!==2)throw Error(`Найдено ${keys.length} непустых вариантов. Для бинарной кодировки нужно ровно два; для остальных меняйте коды в таблице.`);if(!Number.isFinite(a)||!Number.isFinite(b)||a===b)throw Error('Коды должны быть разными числами.');keys.forEach((v,i)=>c.mapping[v]=[a,b][i]);c.value_labels={};invalidate();render();status(`Коды изменены: ${keys[0]} → ${a}; ${keys[1]} → ${b}`)}
function bulk(all){const source=configs[current],fields=bulkOptions.filter(([v])=>$('bulk_'+v).checked).map(([v])=>v);if(!fields.length)throw Error('Выберите настройки для переноса.');const targets=all?configs.map((_,i)=>i):[...chosen];let count=0,unmatched=0;
 for(const i of targets){if(i===current)continue;const t=configs[i];for(const f of fields){if(f==='mode'){t.mode=source.mode;changeMode(t)}if(f==='measure')t.measure=t.mode==='text'?'nominal':source.measure;if(f==='missing'){t.missing_codes=clone(source.missing_codes||[]);t.blank=source.blank;t.missing_tokens=clone(source.missing_tokens||[]);t.reference_missing=[]}if(f==='format'){t.decimals=source.decimals;t.input_format=source.input_format;t.date_display=source.date_display}if(f==='mapping'){
 const sk=answers(source),tk=answers(t);if($('mappingPolicy').value==='order'&&sk.length!==tk.length){unmatched++;continue}
 let m={...t.mapping};tk.forEach((v,j)=>{const k=$('mappingPolicy').value==='order'?sk[j]:sk.find(x=>$('trim').checked?x.trim()===v.trim():x===v);if(k!==undefined&&source.mapping[k]!==undefined)m[v]=source.mapping[k];else unmatched++});t.mapping=m;t.value_labels={};}}
 count++;}invalidate();refreshLists();render();status(`Настройки применены к ${count} переменным. Несопоставленных наборов / ответов: ${unmatched}. Проверьте коды перед экспортом.`)}
$('applySelected').onclick=safe(()=>bulk(false));$('applyAll').onclick=safe(()=>bulk(true));
$('selectAll').onclick=()=>{chosen=new Set(configs.map((_,i)=>i));renderList();renderTargets()};$('selectNone').onclick=()=>{chosen.clear();renderList();renderTargets()};$('search').oninput=renderList;
$('trim').onchange=invalidate;
$('load').onclick=safe(async()=>{if(!$('source').files[0])throw Error('Выберите выгрузку.');status('Читаю данные…');const r=await api('/load',{name:$('source').files[0].name,data:await b64($('source').files[0]),reference:null,sheet:+$('sheet').value-1,header:+$('header').value-1});const d=await r.json();configs=d.configs;current=0;chosen.clear();rules=[];page.row=page.col=0;needsConfirm=d.positional;$('confirm').checked=false;$('confirmLabel').classList.toggle('hidden',!needsConfirm);$('summary').textContent=`${d.rows} респондентов · ${d.columns} переменных`;$('notes').textContent=d.notes.join(' ');$('workspace').classList.remove('hidden');invalidate();refreshLists();render();status('Данные загружены. Настройте переменные и проверьте результат.');});
$('saveTemplate').onclick=safe(()=>download(new Blob([JSON.stringify({version:4,configs,options:{trim:$('trim').checked},rules},null,2)],{type:'application/json'}),'template.json'));
$('template').onchange=safe(async()=>{const doc=JSON.parse(await $('template').files[0].text()),t=Array.isArray(doc)?doc:doc.configs;if(!Array.isArray(t)||t.length!==configs.length||t.some((c,i)=>c.source!==configs[i].source))throw Error('Заголовки или порядок столбцов не совпадают с шаблоном.');configs=t.map((c,i)=>({...configs[i],...c,index:i,frequencies:configs[i].frequencies}));if(doc.options)$('trim').checked=doc.options.trim!==false;rules=doc.rules||[];invalidate();refreshLists();render();status('Настройки применены.');});
async function preview(){const r=await api('/preview',{...payload(),...page,row_count:+$('rowCount').value,col_count:+$('colCount').value,codes:$('showCodes').checked}),d=await r.json();page={...page,total_rows:d.total_rows,total_columns:d.total_columns};const headers=['№ респондента',...d.columns.map(c=>$('showCodes').checked?c.name:c.label+' ('+c.name+')')];$('previewTable').innerHTML=table(headers,d.rows.map((r,i)=>[d.row+i+1,...r]));$('pageInfo').textContent=`Респонденты ${d.row+1}–${d.row+d.rows.length} из ${d.total_rows}; переменные ${d.col+1}–${d.col+d.columns.length} из ${d.total_columns}`;status('Проверка пройдена. Таблица обновлена.');}
$('preview').onclick=safe(()=>{page.row=page.col=0;return preview()});
for(const id of ['showCodes','colCount','rowCount'])$(id).onchange=safe(()=>{page.row=page.col=0;return preview()});
for(const [id,axis,delta,size] of [['prevCols','col',-1,'colCount'],['nextCols','col',1,'colCount'],['prevRows','row',-1,'rowCount'],['nextRows','row',1,'rowCount']])$(id).onclick=safe(()=>{const total=axis==='col'?page.total_columns:page.total_rows;page[axis]=Math.max(0,Math.min(Math.max(0,total-1),page[axis]+delta*+$(size).value));return preview()});
$('export').onclick=safe(async()=>{status('Готовлю Excel и команды SPSS…');const r=await api('/export',{...payload(),rules});download(await r.blob(),'survey_spss.zip');status('Комплект SPSS готов.');});
const operators=[['eq','равно'],['ne','не равно'],['gt','больше'],['lt','меньше'],['missing','пропуск'],['present','не пропуск']];
function renderRules(){const opts=configs.filter(c=>c.include).map(c=>[c.name,c.name+' — '+c.label]);$('rules').innerHTML=rules.map((r,i)=>`<div class="rule"><b>Если</b><div class="row">${select('left'+i,opts,r.left)}${select('left_op'+i,operators,r.left_op)}<input id="left_value${i}" aria-label="Условие ${i+1}" value="${esc(r.left_value)}"></div><b>то запрещено</b><div class="row">${select('right'+i,opts,r.right)}${select('right_op'+i,operators,r.right_op)}<input id="right_value${i}" aria-label="Запрещённое значение ${i+1}" value="${esc(r.right_value)}"></div><button class="secondary" data-delete-rule="${i}">Удалить правило</button></div>`).join('');rules.forEach((r,i)=>{for(const f of ['left','left_op','left_value','right','right_op','right_value'])$(f+i).onchange=()=>{r[f]=$(f+i).value;lastCheck=null;$('checkResults').innerHTML=''}});$('rules').querySelectorAll('[data-delete-rule]').forEach(el=>el.onclick=()=>{rules.splice(+el.dataset.deleteRule,1);renderRules()})}
$('addRule').onclick=()=>{const cs=configs.filter(c=>c.include);if(!cs.length)return;rules.push({left:cs[0].name,left_op:'eq',left_value:'',right:cs[1]?.name||cs[0].name,right_op:'eq',right_value:''});renderRules()};
const selectedValues=id=>[...$(id).selectedOptions].map(o=>o.value);
async function runCheck(kind){const r=await api('/checks',{...payload(),kind,selected:selectedValues('checkVars'),min:$('rangeMin').value,max:$('rangeMax').value,threshold:$('threshold').value,minimum:$('minimum').value,rules});lastCheck=await r.json();$('checkSummary').textContent=`Найдено записей: ${lastCheck.count}. ${lastCheck.note}`;$('checkResults').innerHTML=table(lastCheck.columns,lastCheck.rows);status('Проверка завершена. Результаты показаны в разделе «Проверить данные».');}
$('checkRange').onclick=safe(()=>runCheck('range'));$('checkUniform').onclick=safe(()=>runCheck('uniform'));$('checkLogic').onclick=safe(()=>runCheck('logic'));
$('saveChecks').onclick=safe(()=>{if(!lastCheck)throw Error('Сначала выполните проверку.');const quote=x=>{const value=typeof x==='string'&&/^\s*[=+@-]/.test(x)?"'"+x:String(x??'');return '"'+value.replaceAll('"','""')+'"'};download(new Blob(['\ufeff'+[lastCheck.columns,...lastCheck.rows].map(r=>r.map(quote).join(';')).join('\r\n')],{type:'text/csv;charset=utf-8'}),'data_checks.csv')});
function distPayload(){return {...payload(),selected:selectedValues('distVars'),two_way:$('twoWay').checked,transpose:$('transpose').checked,basis:$('basis').value,fields:[...($('distPercent').checked?['percent']:[]),...($('distValid').checked?['valid']:[]),...($('distCount').checked?['count']:[])]}}
function drawDistributions(d){$('distTables').innerHTML=d.tables.map(t=>`<h3>${esc(t.title)}</h3><p class="muted">${esc(t.note)}</p><div class="scroll">${table(t.columns,t.rows)}</div>`).join('')}
$('distPreview').onclick=safe(async()=>{const r=await api('/distributions',distPayload());drawDistributions(await r.json());status('Распределения рассчитаны.');});
for(const [id,format] of [['distXlsx','xlsx'],['distDocx','docx']])$(id).onclick=safe(async()=>{status('Готовлю файл распределений…');const p=distPayload();const preview=await api('/distributions',p);drawDistributions(await preview.json());const r=await api('/distributions-export',{...p,format});download(await r.blob(),'distributions.'+format);status('Файл распределений готов.');});
